<script setup lang="ts">
import {computed,onMounted,ref,watch,onBeforeUnmount,nextTick} from 'vue'
import {useWorkbench} from './stores/scope'
import {number,percent,ratio,delta,type Product,type View} from './domain/types'
import {exportFile} from './api/client'
import SearchScene from './components/SearchScene.vue'
import ExposureFlow from './components/ExposureFlow.vue'
import CategoryPulse from './components/CategoryPulse.vue'
import PriorityOverview from './components/PriorityOverview.vue'
import DetailPanel from './components/DetailPanel.vue'
import MerchantInsights from './components/MerchantInsights.vue'
import WorkbenchDrawer from './components/WorkbenchDrawer.vue'
import WorkspaceModal from './components/WorkspaceModal.vue'
const store=useWorkbench(),find=ref(''),drawer=ref(''),overlay=ref(''),pane=ref('chart'),filters=ref(false),message=ref(''),busy=ref(false),overlaps=ref<Product[]>([])
let findTimer:ReturnType<typeof setTimeout>|undefined
const sourceMode=computed(()=>store.index?.data_mode==='synthetic'?'演示样本 · 非真实统计':store.index?.data_mode==='authorized_private'?'授权日志 · 私有快照':store.index?.source.sampling?.percent===100?'真实历史全量 · 2025':'真实历史子集 · 2025')
const page=computed(()=>({search:{n:'01',label:'SEARCH DESTINATION',title:'搜索结果，分布在哪些类目？'},flow:{n:'02',label:'EXPOSURE FLOW',title:'曝光如何分布到类目和商品？'},structure:{n:'03',label:'CATEGORY PULSE',title:'曝光与反馈，哪些类目值得深看？'},products:{n:'04',label:'PRODUCT FEEDBACK',title:'哪些商品值得继续查看？'},priority:{n:'05',label:'PRIORITY COMPASS',title:'哪些商品值得先优化？'},compare:{n:'06',label:'FROZEN COHORTS',title:'两组搜索，反馈有何差异？'}}[store.view]))
const totalCategory=computed(()=>store.model?.categories.reduce((n,c)=>n+c.E,0)??0)
watch(()=>store.view,(next,previous)=>{pane.value='chart';if(next==='products'&&(previous==='priority'||previous==='structure'))overlay.value='insights'})
watch(()=>store.model?.scope_id,()=>{pane.value='chart';filters.value=false})
watch(find,text=>{clearTimeout(findTimer);findTimer=setTimeout(()=>store.findQueries(text),220)})
onMounted(()=>store.load(new URLSearchParams(location.search).get('demo')==='1'?'demo':'real'))
onBeforeUnmount(()=>clearTimeout(findTimer))
async function action(fn:()=>Promise<unknown>,success=''){busy.value=true;message.value='';try{await fn();message.value=success}catch(e){message.value=(e as Error).message}finally{busy.value=false}}
async function exportCurrent(format:'json'|'csv'='json'){
 const params:Record<string,unknown>={format,target:store.view==='compare'?'compare':'scope',scope_id:store.model?.scope_id}
 if(store.view==='compare'){params.cohort_a=store.comparison?.a.cohort.cohort_id;params.cohort_b=store.comparison?.b.cohort.cohort_id}
 await action(()=>exportFile(params,text=>message.value=text),'导出完成，文件已下载')
}
async function switchView(view:View){await store.setView(view);pane.value='chart';overlay.value='';filters.value=false}
function splitChange(event:Event){const value=(event.target as HTMLSelectElement).value;store.splitPolicy=value==='all'?(store.index?.splits??[]):[value];store.select('ALL')}
</script>
<template>
<header class="topbar" :inert="!!drawer"><a class="brand" href="/" aria-label="购序首页"><span class="brand-mark"><i/><i/><i/></span>购序<span class="edition">SEARCH / 3D</span></a><nav aria-label="主导航"><button v-for="(label,key) in {search:'搜索去向',flow:'曝光流向',structure:'类目体检',products:'商品表现',priority:'优化罗盘',compare:'两组对照'}" :key="key" :class="{active:store.view===key}" :disabled="!store.model" @click="switchView(key)">{{label}}</button></nav><div class="header-end"><span v-if="store.index" class="data-badge" :class="{demo:store.index.data_mode==='synthetic'}"><i/>{{sourceMode}}</span><button class="text-button" @click="drawer='reviews'">复核清单 <b>{{store.reviews.length}}</b></button><button class="text-button" @click="drawer='source'">数据与口径 ↗</button></div></header>
<main :inert="!!drawer" :class="{'filters-open':filters}">
 <div v-if="message" class="notice" role="status">{{message}}<button aria-label="关闭提示" @click="message=''">×</button></div>
 <section v-if="!store.index&&!store.loading" class="onboarding"><span class="eyebrow">GOUXU / 搜索复盘</span><h1>从一次搜索，读懂商品去向。</h1><p>选择已核验的数据快照，开始查看曝光、点击与购买反馈。</p><div class="source-card"><span class="source-icon">↗</span><div><h2>KuaiSearch-Lite 历史数据</h2><p>{{store.error||'当前环境还没有已核验的真实快照。'}}</p></div><button @click="store.load()">刷新快照</button></div><button class="demo-entry" @click="store.load('demo')">进入合成演示 · 336 请求 / 28 商品 →</button><button class="secondary-button" @click="drawer='import'">导入授权日志</button></section>
 <template v-else-if="store.index&&store.model">
 <section class="page-heading" :class="{'priority-heading':store.view==='priority'}"><div><p class="eyebrow">{{page.n}} / {{page.label}}</p><h1>{{page.title}}</h1></div><div class="headline-stats" v-if="store.view!=='compare'"><div><strong>{{number(store.model.requests)}}</strong><span>搜索请求 <small>条</small></span></div><div><strong>{{number(store.model.E)}}</strong><span>曝光配对 <small>条</small></span></div><div><strong>{{percent(ratio(store.model.C,store.model.E))}}</strong><span>匹配点击占比</span></div></div><div v-else-if="store.comparison" class="headline-stats"><div><strong>{{delta(store.comparison.click_delta_pp)}}</strong><span>点击差异 <small>百分点 B − A</small></span></div><div><strong>{{delta(store.comparison.purchase_delta_pp)}}</strong><span>购买反馈差异 <small>百分点 B − A</small></span></div></div></section>
 <div v-if="store.loading||store.compareLoading||store.error" class="load-status" role="status">{{store.error||'正在读取新范围…'}}<span>当前显示上一结果</span><button v-if="store.error" @click="store.select(store.query,store.queryKey==='saved'?'all':store.queryKey)">重试</button></div>
 <section class="view-controls" :class="{'priority-controls':store.view==='priority'}"><label>快照<select :value="store.index.snapshot_id" aria-label="选择数据快照" @change="store.load(store.mode,($event.target as HTMLSelectElement).value)"><option v-for="s in store.snapshots" :key="s.snapshot_id" :value="s.snapshot_id">{{s.title}}</option></select></label><label>拆分<select :value="store.view==='compare'&&store.comparison?(store.comparison.a.model.split_policy.length===1?store.comparison.a.model.split_policy[0]:'all'):(store.splitPolicy.length===1?store.splitPolicy[0]:'all')" :disabled="store.view==='compare'" aria-label="拆分策略" @change="splitChange"><option value="all">全部 split</option><option v-for="s in store.index.splits" :key="s">{{s}}</option></select></label><button class="text-button" @click="drawer='import'">导入数据 ＋</button><template v-if="(store.view==='products'||store.view==='priority')"><button class="text-button" @click="drawer='products'">查找商品 ↗</button><label v-if="store.view==='products'">纵轴<select v-model="store.metric" aria-label="商品纵轴"><option value="click">匹配点击占比</option><option value="purchase_feedback">购买反馈占比</option></select></label><label>{{store.view==='priority'?'候选数量':'显示'}}<select v-model.number="store.topK" aria-label="商品显示数量" @change="store.refreshProducts()"><option :value="16">16 件</option><option :value="32">32 件</option><option :value="64">64 件</option></select></label><label>{{store.view==='priority'?'候选最低曝光':'最低曝光'}}<input v-model.number="store.minPairs" type="number" min="0" max="1000000" aria-label="最低曝光显示门槛" @change="store.refreshProducts()"></label></template><template v-else-if="store.view==='compare'"><button class="group-chip" @click="drawer='groups'">A {{store.comparison?.a.cohort.name||'…'}} / B {{store.comparison?.b.cohort.name||'…'}} <span>编辑 ↗</span></button><button class="text-button" :disabled="!store.comparison||store.compareLoading" @click="store.sameGroup()">同组检查</button></template></section>
 <div class="workspace-tools" :class="{'priority-tools':store.view==='priority'}"><div class="pane-switch" role="group" aria-label="工作区面板"><button v-for="(label,key) in {chart:'图表',queries:'查询',details:'详情'}" :key="key" :class="{active:pane===key}" :aria-pressed="pane===key" @click="pane=key">{{label}}</button></div><div class="workspace-tool-actions"><button v-if="store.view!=='priority'&&store.view!=='structure'" @click="overlay='insights'">商家解读 ↗</button><button @click="overlay='readings'">精确读数 ↗</button><button class="filters-toggle" :aria-expanded="filters" @click="filters=!filters">{{filters?'收起筛选':'筛选'}}</button></div></div>
 <WorkspaceModal v-if="overlay==='insights'&&store.view!=='priority'" title="商家解读与优化建议" @close="overlay=''"><MerchantInsights @save="note=>action(()=>store.saveReview(note),'诊断与优化待办已保存到复核清单')" @evidence="overlay='';drawer='evidence'"/></WorkspaceModal>
 <section class="workspace" :data-pane="pane" :class="{'priority-workspace':store.view==='priority'||store.view==='structure'}"><aside class="query-panel"><div class="panel-heading">分析范围<span>{{number(store.index.counts.queries)}} 个查询</span></div><label class="query-search"><span>⌕</span><input v-model="find" type="search" placeholder="查找查询词" aria-label="查找查询，不改变分析范围"></label><button class="all-query" :class="{selected:store.queryKey==='all'}" @click="store.select('ALL')"><span>◈</span> 全部查询<strong>{{number(store.index.counts.requests)}} 请求</strong></button><p class="query-sort-note">按快照曝光排序 · 右侧为曝光配对数</p><div class="query-list"><button v-for="(q,i) in store.queries" :key="q.key" :class="{selected:store.queryKey===q.key}" @click="store.select(q.query,q.key)"><span class="query-index">{{String(i+1).padStart(2,'0')}}</span><span class="query-name" :title="q.query">{{q.query||'空查询'}}</span><small :title="'曝光配对数：'+number(q.E??q.requests)">{{number(q.E??q.requests)}}</small></button><p v-if="!store.queries.length" class="muted">没有匹配的查询</p></div><div class="query-note"><span>{{store.view==='compare'?'查询组已冻结':'范围与聚焦'}}</span><p>{{store.view==='compare'?'左侧选择不改变已冻结的 A / B。请用“编辑”更新两组。':(store.view==='products'||store.view==='priority')?'显示数量和曝光门槛只影响图中商品，范围分母保持完整。':'选择查询更新范围；类目按当前范围曝光排序，选择类目只改变聚焦。'}}</p></div><div class="source-mini"><span class="source-led"/><div>{{store.index.data_mode==='synthetic'?'合成样本':'历史搜索日志'}}<small>{{store.index.data_mode==='synthetic'?'界面演示专用':'保留原始相对时间索引'}}</small></div></div></aside>
 <CategoryPulse v-if="store.view==='structure'" @inspect="pane='details'" @evidence="drawer='evidence'"/><ExposureFlow v-else-if="store.view==='flow'"/><PriorityOverview v-else-if="store.view==='priority'" :busy="busy" @inspect="pane='details'" @save="note=>action(()=>store.saveReview(note),'检查建议已保存到复核清单')" @evidence="drawer='evidence'"/><SearchScene v-else @overlap="members=>{overlaps=members;drawer='overlap'}"/>
 <DetailPanel v-if="store.view!=='priority'&&store.view!=='structure'" @insights="overlay='insights'" @evidence="drawer='evidence'" @export="exportCurrent()" @save="action(()=>store.saveReview(),'已加入复核清单')" @other="drawer='other'"/>
 </section>
 <WorkspaceModal v-if="overlay==='readings'" title="精确读数" @close="overlay=''"><section class="precise-section"><div class="readings-summary"><span>精确读数</span><small>{{(store.view==='products'||store.view==='priority')?'当前显示 '+store.products.length+' 件 / 达到门槛 '+store.eligibleTotal+' 件':store.view==='compare'?'两组独立分母 · 相同类目量尺':store.model.categories.length+' 个真实类目 · 合计 '+number(totalCategory)+' 条曝光'}}</small></div><div class="table-scroll"><table v-if="store.view!=='compare'"><thead><tr><th>{{(store.view==='products'||store.view==='priority')?'商品':'类目'}}</th><th>曝光配对数</th><th>匹配点击</th><th>购买反馈</th><th>点击占比</th><th>购买反馈占比</th></tr></thead><tbody><tr v-for="c in (store.view==='products'||store.view==='priority')?store.products:store.model.categories" :key="c.id"><td><button @click="(store.view==='products'||store.view==='priority')?store.selectItem(c.id):store.setCategory(c.id)">{{'title' in c?c.title:c.name}}</button></td><td>{{number(c.E)}}</td><td>{{number(c.C)}}</td><td>{{number(c.P)}}</td><td>{{percent(ratio(c.C,c.E))}}</td><td>{{percent(ratio(c.P,c.E))}}</td></tr></tbody></table><table v-else><thead><tr><th>类目</th><th>A 曝光</th><th>A 组内占比</th><th>B 曝光</th><th>B 组内占比</th><th>B − A（百分点）</th></tr></thead><tbody><tr v-for="c in store.comparison?.categories" :key="c.id"><td><button @click="store.setCategory(c.id)">{{c.name}}</button></td><td>{{number(c.aE)}}</td><td>{{percent(c.a)}}</td><td>{{number(c.bE)}}</td><td>{{percent(c.b)}}</td><td>{{delta(c.a==null||c.b==null?null:(c.b-c.a)*100)}}</td></tr></tbody></table></div></section></WorkspaceModal>
 <footer><span>同请求同商品计1配对 · 购买反馈≠支付订单</span><span><button v-if="store.view==='priority'" @click="overlay='readings'">精确读数 · </button><button :disabled="busy" @click="exportCurrent('json')">JSON 导出</button> / <button :disabled="busy" @click="exportCurrent('csv')">CSV 导出</button></span></footer>
 </template><div v-else class="loading-screen" role="status">{{store.error||'正在读取快照…'}}<button v-if="store.error" class="secondary-button" @click="store.load(store.mode,store.index?.snapshot_id)">重新读取快照</button></div>
</main>
<WorkbenchDrawer v-if="drawer" :kind="drawer" :overlaps="overlaps" @close="drawer=''"/>
</template>





<style src="./theme/viewport.css"></style>
